SourceCode.Declaration:
/// <summary>
/// Sets or resets a mobile user's password.
///
/// Prompts rather than taking the password from a field, because a password typed into a bound
/// control ends up in the form's state, in a trace, and on the screen of a shared workstation.
/// </summary>
class HSMobileOpsSetPassword
{

}

Method.Source:
public static void main(Args _args)
{
    HSMobileOpsUser user;
    Dialog          dialog;
    DialogField     passwordField;
    DialogField     confirmField;

    if (!_args || !_args.record() || _args.dataset() != tableNum(HSMobileOpsUser))
    {
        throw error('Select a mobile user first');
    }

    user = _args.record() as HSMobileOpsUser;

    dialog        = new Dialog('Set handheld password');
    passwordField = dialog.addField(extendedTypeStr(Password), 'New password');
    confirmField  = dialog.addField(extendedTypeStr(Password), 'Confirm');

    dialog.addText(strFmt(
        '%1 must change this at their next sign-in.', user.UserName));

    if (!dialog.run())
    {
        return;
    }

    // Confirmed rather than trusted. A mistyped password an administrator cannot see is one
    // the worker cannot sign in with and nobody can explain.
    if (passwordField.value() != confirmField.value())
    {
        throw error('The two passwords do not match');
    }

    HSMobileOpsUserAdmin::setPassword(user, passwordField.value());
}
